using System;
using System.Globalization;
using System.Linq;
using System.Text.RegularExpressions;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Documents;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Threading;
internal static class CoordinateLinks {
 static readonly Regex Pattern=new Regex(@"\[\s*([+\-−]?\d{1,3})\s*,\s*([+\-−]?\d{1,3})\s*\]",RegexOptions.CultureInvariant);
 internal static TextBlock Decorate(TextBlock text,Brush accent,Func<bool> allowed=null,Action<string> copy=null){string original=text.Text??"";var matches=Pattern.Matches(original);if(matches.Count==0)return text;text.Inlines.Clear();int offset=0;foreach(Match match in matches){if(match.Index>offset)text.Inlines.Add(new Run(original.Substring(offset,match.Index-offset)));int x,y;if(!Int32.TryParse(match.Groups[1].Value.Replace('−','-'),NumberStyles.AllowLeadingSign,CultureInfo.InvariantCulture,out x)||!Int32.TryParse(match.Groups[2].Value.Replace('−','-'),NumberStyles.AllowLeadingSign,CultureInfo.InvariantCulture,out y)){text.Inlines.Add(new Run(match.Value));offset=match.Index+match.Length;continue;}string command="/travel "+x.ToString(CultureInfo.InvariantCulture)+","+y.ToString(CultureInfo.InvariantCulture);var run=new Run(match.Value);var link=new Hyperlink(run){Foreground=accent,Cursor=Cursors.Hand,ToolTip="Cliquer pour copier "+command,Tag=command};link.Click+=delegate{if(allowed!=null&&!allowed())return;try{if(copy==null)Clipboard.SetText(command);else copy(command);run.Text=match.Value+" ✓";link.ToolTip="Copié : "+command;var timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1.6)};timer.Tick+=delegate{timer.Stop();run.Text=match.Value;link.ToolTip="Cliquer pour copier "+command;};timer.Start();}catch(Exception){link.ToolTip="Copie indisponible. Réessayez.";}};text.Inlines.Add(link);offset=match.Index+match.Length;}if(offset<original.Length)text.Inlines.Add(new Run(original.Substring(offset)));return text;}
 internal static void Test(){string copied="";bool allowed=true;var text=Decorate(new TextBlock{Text="Aller [-3, 12], puis [0,-1] et [+2,−4]. Garder [1000,2] et [texte]."},Brushes.Orange,()=>allowed,value=>copied=value);var links=text.Inlines.OfType<Hyperlink>().ToList();if(links.Count!=3)throw new Exception("Positions valides et invalides");links[0].RaiseEvent(new RoutedEventArgs(Hyperlink.ClickEvent));if(copied!="/travel -3,12"||!new TextRange(text.ContentStart,text.ContentEnd).Text.Contains("✓"))throw new Exception("Copie première coordonnée et retour visuel");links[1].RaiseEvent(new RoutedEventArgs(Hyperlink.ClickEvent));if(copied!="/travel 0,-1")throw new Exception("Copie indépendante de chaque lien");links[2].RaiseEvent(new RoutedEventArgs(Hyperlink.ClickEvent));if(copied!="/travel 2,-4")throw new Exception("Signe et normalisation");allowed=false;copied="";links[0].RaiseEvent(new RoutedEventArgs(Hyperlink.ClickEvent));if(copied!="")throw new Exception("Copie désactivée en aperçu ou mode discret");var failed=Decorate(new TextBlock{Text="[1,2]"},Brushes.Orange,null,value=>{throw new System.Runtime.InteropServices.ExternalException();});var failure=failed.Inlines.OfType<Hyperlink>().Single();failure.RaiseEvent(new RoutedEventArgs(Hyperlink.ClickEvent));if(!Convert.ToString(failure.ToolTip).Contains("indisponible"))throw new Exception("Presse-papiers occupé");}

}
